// Fix stale /careers canonical URLs on the merged EN pages after the route was
// renamed /careers -> /team. Locale copies are regenerated by build-locales.js
// from the EN pages, so this only ever touches the EN root.
//
// fixCanonical(mergedRoot, log) -> { fixed: N }

const fs = require('fs');
const path = require('path');

const LOCALES = new Set(['nl', 'de', 'fr', 'es', 'it', 'zh']);
const PAIRS = [
  ['https://www.rhinesolution.com/careers', 'https://www.rhinesolution.com/team'],
  ['https://rhinesolution.com/careers', 'https://rhinesolution.com/team'],
];

function enPageHtmlFiles(root) {
  const files = [];
  for (const entry of fs.readdirSync(root, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      if (LOCALES.has(entry.name)) continue;
      const idx = path.join(root, entry.name, 'index.html');
      if (fs.existsSync(idx)) files.push(idx);
    }
  }
  const rootIdx = path.join(root, 'index.html');
  if (fs.existsSync(rootIdx)) files.push(rootIdx);
  return files;
}

function fixCanonical(mergedRoot, log) {
  const files = enPageHtmlFiles(mergedRoot);
  let fixed = 0;
  for (const f of files) {
    const text = fs.readFileSync(f, 'utf8');
    let changed = 0;
    let out = text;
    for (const [from, to] of PAIRS) {
      const n = out.split(from).length - 1;
      if (n > 0) {
        out = out.split(from).join(to);
        changed += n;
      }
    }
    if (changed > 0) {
      fs.writeFileSync(f, out, 'utf8');
      fixed += changed;
      if (log) console.log(`    [fix-canonical] ${changed}x ${path.relative(mergedRoot, f).replace(/\\/g, '/')}`);
    }
  }
  if (log && fixed) console.log('  fix-canonical: rewrote', fixed, '/careers canonical URLs to /team');
  return { fixed };
}

module.exports = { fixCanonical };